KG_CODE("f:vendor/kgraph-2.2/kgraph/scripts/kg/selftest.py","\"\"\"`kgraph.py selftest` — build a corpus covering every format family with the standard library only,\nrun the full pipeline, and assert the expected nodes/edges. Engine-dependent checks (OCR, speech)\nrun when an engine exists and are reported as SKIP otherwise.\"\"\"\nfrom __future__ import annotations\n\nimport io\nimport json\nimport shutil\nimport sqlite3\nimport struct\nimport sys\nimport tempfile\nimport time\nimport zipfile\nimport zlib\nfrom pathlib import Path\n\n# ------------------------------------------------------------------ tiny bitmap font for an OCR image\nFONT = {\n    \"A\": [\"01110\", \"10001\", \"10001\", \"11111\", \"10001\", \"10001\", \"10001\"], \"C\": [\"01111\", \"10000\", \"10000\", \"10000\", \"10000\", \"10000\", \"01111\"],\n    \"G\": [\"01111\", \"10000\", \"10000\", \"10111\", \"10001\", \"10001\", \"01111\"], \"H\": [\"10001\", \"10001\", \"10001\", \"11111\", \"10001\", \"10001\", \"10001\"],\n    \"K\": [\"10001\", \"10010\", \"10100\", \"11000\", \"10100\", \"10010\", \"10001\"], \"O\": [\"01110\", \"10001\", \"10001\", \"10001\", \"10001\", \"10001\", \"01110\"],\n    \"P\": [\"11110\", \"10001\", \"10001\", \"11110\", \"10000\", \"10000\", \"10000\"], \"R\": [\"11110\", \"10001\", \"10001\", \"11110\", \"10100\", \"10010\", \"10001\"],\n    \"T\": [\"11111\", \"00100\", \"00100\", \"00100\", \"00100\", \"00100\", \"00100\"], \"E\": [\"11111\", \"10000\", \"10000\", \"11110\", \"10000\", \"10000\", \"11111\"],\n    \"S\": [\"01111\", \"10000\", \"10000\", \"01110\", \"00001\", \"00001\", \"11110\"], \" \": [\"00000\"] * 7,\n}\n\n\ndef png_text(text, scale=10):\n    rows = 7 * scale + 40\n    cols = len(text) * 6 * scale + 40\n    pix = [[255] * cols for _ in range(rows)]\n    for i, ch in enumerate(text):\n        glyph = FONT.get(ch, FONT[\" \"])\n        for gy, line in enumerate(glyph):\n            for gx, bit in enumerate(line):\n                if bit == \"1\":\n                    for y in range(scale):\n                        for x in range(scale):\n                            pix[20 + gy * scale + y][20 + (i * 6 + gx) * scale + x] = 0\n    raw = b\"\".join(b\"\\x00\" + bytes(r) for r in pix)\n\n    def chunk(t, d):\n        return struct.pack(\">I\", len(d)) + t + d + struct.pack(\">I\", zlib.crc32(t + d) & 0xFFFFFFFF)\n    return (b\"\\x89PNG\\r\\n\\x1a\\n\" + chunk(b\"IHDR\", struct.pack(\">IIBBBBB\", cols, rows, 8, 0, 0, 0, 0))\n            + chunk(b\"IDAT\", zlib.compress(raw, 9)) + chunk(b\"IEND\", b\"\"))\n\n\n# ------------------------------------------------------------------ minimal OLE2 + VBA project writer\n\ndef ovba_literal_compress(data: bytes) -> bytes:\n    out = bytearray(b\"\\x01\")\n    for i in range(0, max(1, len(data)), 4096):\n        chunk = data[i:i + 4096]\n        body = bytearray()\n        for j in range(0, len(chunk), 8):\n            group = chunk[j:j + 8]\n            body.append(0)  # all 8 tokens are literals\n            body += group\n        out += struct.pack(\"<H\", 0xB000 | (len(body) + 2 - 3)) + body\n    return bytes(out)\n\n\ndef cfb_write(streams):\n    \"\"\"streams: {\"VBA/dir\": bytes, \"VBA/Module1\": bytes} (single storage level). mini-cutoff 0 so every stream\n    uses regular sectors — readable by kgraph's reader (test fixture only).\"\"\"\n    SEC = 512\n    names = sorted(streams)\n    storage = names[0].split(\"/\")[0]\n    entries = [(\"Root Entry\", 5), (storage, 1)] + [(n.split(\"/\")[1], 2) for n in names]\n    data_secs, starts, fat = bytearray(), {}, []\n    sec_index = 0\n    for n in names:\n        blob = streams[n]\n        nsec = max(1, -(-len(blob) // SEC))\n        starts[n] = sec_index\n        data_secs += blob + b\"\\x00\" * (nsec * SEC - len(blob))\n        fat += [sec_index + k + 1 for k in range(nsec - 1)] + [0xFFFFFFFE]\n        sec_index += nsec\n    dir_start = sec_index\n    dir_bytes = bytearray()\n    child_ids = list(range(2, 2 + len(names)))\n    for idx, (name, typ) in enumerate(entries):\n        e = bytearray(128)\n        u = name.encode(\"utf-16-le\")\n        e[:len(u)] = u\n        struct.pack_into(\"<H\", e, 64, len(u) + 2)\n        e[66], e[67] = typ, 1\n        left = right = child = 0xFFFFFFFF\n        if idx == 0:\n            child = 1\n        elif idx == 1:\n            child = child_ids[0]\n        elif idx >= 2:\n            right = idx + 1 if idx + 1 < 2 + len(names) else 0xFFFFFFFF\n        struct.pack_into(\"<III\", e, 68, left, right, child)\n        if typ == 2:\n            n = names[idx - 2]\n            struct.pack_into(\"<I\", e, 116, starts[n])\n            struct.pack_into(\"<I\", e, 120, len(streams[n]))\n        else:\n            struct.pack_into(\"<I\", e, 116, 0xFFFFFFFE)\n        dir_bytes += e\n    dir_bytes += b\"\\x00\" * (-len(dir_bytes) % SEC)\n    ndir = len(dir_bytes) // SEC\n    fat += [dir_start + k + 1 for k in range(ndir - 1)] + [0xFFFFFFFE]\n    fat_sec = dir_start + ndir\n    fat += [0xFFFFFFFD]\n    fat += [0xFFFFFFFF] * (-len(fat) % (SEC // 4))\n    header = bytearray(512)\n    header[:8] = b\"\\xd0\\xcf\\x11\\xe0\\xa1\\xb1\\x1a\\xe1\"\n    struct.pack_into(\"<HHHHH\", header, 0x18, 0x3E, 3, 0xFFFE, 9, 6)\n    struct.pack_into(\"<IIIIIIII\", header, 0x2C, 1, dir_start, 0, 0, 0xFFFFFFFE, 0, 0xFFFFFFFE, 0)\n    difat = [fat_sec] + [0xFFFFFFFF] * 108\n    struct.pack_into(\"<109I\", header, 0x4C, *difat)\n    return bytes(header) + bytes(data_secs) + bytes(dir_bytes) + struct.pack(f\"<{len(fat)}I\", *fat)\n\n\ndef vba_project(modules):\n    d = bytearray()\n\n    def rec(rid, payload):\n        d.extend(struct.pack(\"<HI\", rid, len(payload)) + payload)\n    rec(0x0003, struct.pack(\"<H\", 1252))\n    streams = {}\n    for name, code in modules.items():\n        rec(0x0019, name.encode(\"cp1252\"))\n        rec(0x001A, name.encode(\"cp1252\"))\n        rec(0x0031, struct.pack(\"<I\", 0))\n        rec(0x0021, b\"\")\n        streams[f\"VBA/{name}\"] = ovba_literal_compress(f'Attribute VB_Name = \"{name}\"\\r\\n{code}'.encode(\"cp1252\"))\n    d.extend(struct.pack(\"<HI\", 0x002B, 0))\n    streams[\"VBA/dir\"] = ovba_literal_compress(bytes(d))\n    return cfb_write(streams)\n\n\ndef xlsx_with_macro(path, macro_code):\n    W = ('xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" '\n         'xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"')\n\n    def rels(items):\n        return ('<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">'\n                + \"\".join(f'<Relationship Id=\"{i}\" Type=\"t\" Target=\"{t}\"/>' for i, t in items) + \"</Relationships>\")\n    with zipfile.ZipFile(path, \"w\") as z:\n        z.writestr(\"[Content_Types].xml\", '<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"/>')\n        z.writestr(\"xl/workbook.xml\", f'<?xml version=\"1.0\"?><workbook {W}><sheets><sheet name=\"Data Sheet\" sheetId=\"1\" r:id=\"rId1\"/>'\n                                      f'<sheet name=\"Summary\" sheetId=\"2\" r:id=\"rId2\"/></sheets></workbook>')\n        z.writestr(\"xl/_rels/workbook.xml.rels\", rels([(\"rId1\", \"worksheets/sheet1.xml\"), (\"rId2\", \"worksheets/sheet2.xml\")]))\n        z.writestr(\"xl/sharedStrings.xml\", f'<?xml version=\"1.0\"?><sst {W}><si><t>Employee</t></si><si><t>Salary</t></si></sst>')\n        z.writestr(\"xl/worksheets/sheet1.xml\", f'<?xml version=\"1.0\"?><worksheet {W}><sheetPr codeName=\"Sheet1\"/><sheetData>'\n                                               f'<row r=\"1\"><c r=\"A1\" t=\"s\"><v>0</v></c><c r=\"B1\" t=\"s\"><v>1</v></c></row></sheetData></worksheet>')\n        z.writestr(\"xl/worksheets/_rels/sheet1.xml.rels\", rels([(\"rId1\", \"../drawings/drawing1.xml\")]))\n        z.writestr(\"xl/drawings/drawing1.xml\", '<?xml version=\"1.0\"?><xdr:wsDr xmlns:xdr=\"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\">'\n                                              '<xdr:sp macro=\"[0]!RefreshSummary\"/></xdr:wsDr>')\n        z.writestr(\"xl/worksheets/sheet2.xml\", f'<?xml version=\"1.0\"?><worksheet {W}><sheetData><row r=\"1\">'\n                                               f\"<c r=\\\"A1\\\"><f>SUM('Data Sheet'!B2:B9)</f></c></row></sheetData></worksheet>\")\n        z.writestr(\"xl/vbaProject.bin\", vba_project({\"Payroll\": macro_code}))\n\n\ndef pdf_simple(lines):\n    content = \"BT /F1 14 Tf 72 720 Td 18 TL \" + \" \".join(f\"({ln}) Tj T*\" for ln in lines) + \" ET\"\n    objs = [\"<< /Type /Catalog /Pages 2 0 R >>\", \"<< /Type /Pages /Kids [3 0 R] /Count 1 >>\",\n            \"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>\",\n            None, \"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\"]\n    data = zlib.compress(content.encode(\"latin-1\"))\n    out = bytearray(b\"%PDF-1.4\\n\")\n    for i, o in enumerate(objs, 1):\n        out += f\"{i} 0 obj\\n\".encode()\n        if o is None:\n            out += f\"<< /Length {len(data)} /Filter /FlateDecode >>\\nstream\\n\".encode() + data + b\"\\nendstream\"\n        else:\n            out += o.encode()\n        out += b\"\\nendobj\\n\"\n    out += b\"trailer << /Root 1 0 R >>\\n%%EOF\"\n    return bytes(out)\n\n\ndef make_corpus(root: Path):\n    (root / \"src\").mkdir(parents=True)\n    (root / \"docs\").mkdir()\n    (root / \"data\").mkdir()\n    (root / \"media\").mkdir()\n    (root / \"src\" / \"payroll.py\").write_text(\n        \"from tax import calculate_net\\n\\nclass PayrollService:\\n    def run(self, gross):\\n\"\n        \"        # WHY: keep tax rules out of the UI\\n        return calculate_net(gross)\\n\", encoding=\"utf-8\")\n    (root / \"src\" / \"tax.py\").write_text(\"def calculate_net(gross):\\n    return apply_rate(gross)\\n\\ndef apply_rate(g):\\n    return g * 0.8\\n\", encoding=\"utf-8\")\n    (root / \"src\" / \"ui.ts\").write_text('import { format } from \"./fmt\";\\nexport class Screen { show(){ return format(1); } }\\n', encoding=\"utf-8\")\n    (root / \"src\" / \"fmt.ts\").write_text(\"export function format(n: number) { return n.toFixed(2); }\\n\", encoding=\"utf-8\")\n    (root / \"src\" / \"Mailer.bas\").write_text('Attribute VB_Name = \"Mailer\"\\nSub SendTrainingPlan()\\n    Call BuildBody\\nEnd Sub\\nFunction BuildBody()\\nEnd Function\\n', encoding=\"utf-8\")\n    (root / \"src\" / \"schema.sql\").write_text(\"CREATE TABLE dept(id INT);\\nCREATE TABLE emp(id INT, d INT REFERENCES dept(id));\\n\", encoding=\"utf-8\")\n    (root / \"src\" / \"main.tf\").write_text('resource \"aws_s3_bucket\" \"reports\" {}\\nresource \"aws_lambda_function\" \"mailer\" {\\n  env = aws_s3_bucket.reports.id\\n}\\n', encoding=\"utf-8\")\n    (root / \"docs\" / \"architecture.md\").write_text(\"# Architecture\\nThe `PayrollService` calls `calculate_net`. See [setup](setup.md).\\nDecision: macros stay in VBA.\\n\", encoding=\"utf-8\")\n    (root / \"docs\" / \"setup.md\").write_text(\"# Setup\\nRun `schema.sql`.\\n\", encoding=\"utf-8\")\n    (root / \"docs\" / \"brief.pdf\").write_bytes(pdf_simple([\"Training brief\", \"SendTrainingPlan emails managers\"]))\n    with zipfile.ZipFile(root / \"docs\" / \"policy.docx\", \"w\") as z:\n        z.writestr(\"word/document.xml\", '<?xml version=\"1.0\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>'\n                   '<w:p><w:pPr><w:pStyle w:val=\"Heading1\"/></w:pPr><w:r><w:t>Leave Policy</w:t></w:r></w:p>'\n                   '<w:p><w:r><w:t>PayrollService pays leave.</w:t></w:r></w:p></w:body></w:document>')\n    xlsx_with_macro(root / \"data\" / \"tool.xlsm\",\n                    'Sub RefreshSummary()\\r\\n    ThisWorkbook.Sheets(\"Summary\").Range(\"A1\").Calculate\\r\\n    ReadData\\r\\nEnd Sub\\r\\n'\n                    'Sub ReadData()\\r\\n    Worksheets(\"Data Sheet\").Activate\\r\\n    Sheets(\"Ghost\").Select\\r\\nEnd Sub\\r\\n')\n    (root / \"data\" / \"people.csv\").write_text(\"Employee,Department,Salary\\nA,HR,9000\\n\", encoding=\"utf-8\")\n    con = sqlite3.connect(root / \"data\" / \"hr.sqlite\")\n    con.executescript(\"CREATE TABLE dept(id INTEGER PRIMARY KEY);CREATE TABLE emp(id INTEGER, d INTEGER REFERENCES dept(id));\")\n    con.commit()\n    con.close()\n    (root / \"data\" / \"mail.eml\").write_text(\"From: HR <hr@example.org>\\nTo: Team <team@example.org>\\nSubject: Launch\\n\\nSendTrainingPlan goes live.\\n\", encoding=\"utf-8\")\n    nb = {\"cells\": [{\"cell_type\": \"code\", \"source\": [\"def load_people(p):\\n\", \"    return p\\n\"]}], \"metadata\": {}, \"nbformat\": 4}\n    (root / \"data\" / \"analysis.ipynb\").write_text(json.dumps(nb), encoding=\"utf-8\")\n    with zipfile.ZipFile(root / \"data\" / \"tools.zip\", \"w\") as z:\n        z.writestr(\"cleanup.py\", \"def purge_rows():\\n    return 1\\n\")\n    (root / \"media\" / \"ocr_card.png\").write_bytes(png_text(\"KGRAPH OCR TEST\"))\n    wav = io.BytesIO()\n    rate, samples = 8000, b\"\\x00\\x00\" * 8000\n    wav.write(b\"RIFF\" + struct.pack(\"<I\", 36 + len(samples)) + b\"WAVEfmt \" + struct.pack(\"<IHHIIHH\", 16, 1, 1, rate, rate * 2, 2, 16)\n              + b\"data\" + struct.pack(\"<I\", len(samples)) + samples)\n    (root / \"media\" / \"note.wav\").write_bytes(wav.getvalue())\n    (root / \"media\" / \"note.srt\").write_text(\"1\\n00:00:00,000 --> 00:00:01,000\\nPayrollService review meeting\\n\", encoding=\"utf-8\")\n\n\ndef run(verbose=True, keep=False):\n    from . import native, ocr\n    from .build import build\n    from .graph import Graph\n    from .query import explain, path, query\n    import os as _os\n    _os.environ[\"KGRAPH_NO_REUSE\"] = \"1\"  # fixtures must neither reuse nor register real knowledge bases\n    tmp = Path(tempfile.mkdtemp(prefix=\"kgraph_selftest_\"))\n    corpus = tmp / \"corpus\"\n    results = []\n\n    def check(name, ok, detail=\"\"):\n        results.append((name, \"PASS\" if ok is True else (\"SKIP\" if ok is None else \"FAIL\"), detail))\n\n    t0 = time.time()\n    make_corpus(corpus)\n    res = build(corpus, quiet=True)\n    g = Graph.load(Path(res[\"out\"]) / \"graph.json\")\n    labels = {n[\"label\"]: nid for nid, n in g.nodes.items()}\n\n    def has_edge(src_label, rel, dst_label):\n        s, d = labels.get(src_label), labels.get(dst_label)\n        return bool(s and d and any(e[\"target\"] == d and e[\"relation\"] == rel for e in g.out.get(s, [])))\n\n    check(\"build: no extraction errors\", not res[\"errors\"], \"; \".join(res[\"errors\"][:3]))\n    check(\"python: method calls imported function\", has_edge(\".run()\", \"calls\", \"calculate_net()\"))\n    check(\"python: rationale comment captured\", any(n[\"type\"] == \"rationale\" for n in g.nodes.values()))\n    check(\"typescript: named import resolved\", has_edge(\".show()\", \"calls\", \"format()\"))\n    check(\"vba (.bas): Call statement\", has_edge(\"SendTrainingPlan()\", \"calls\", \"BuildBody()\"))\n    check(\"sql: foreign key\", has_edge(\"emp\", \"references\", \"dept\"))\n    check(\"terraform: resource reference\", has_edge(\"aws_lambda_function.mailer\", \"references\", \"aws_s3_bucket.reports\"))\n    check(\"markdown: link + code mention\", has_edge(\"Architecture\", \"references\", \"setup.md\") and has_edge(\"Architecture\", \"mentions\", \"PayrollService\"))\n    check(\"pdf: text extracted + mention\", has_edge(\"brief.pdf\", \"mentions\", \"SendTrainingPlan()\"))\n    check(\"docx: heading section\", \"Leave Policy\" in labels)\n    check(\"xlsm: cross-sheet formula\", has_edge(\"Summary (sheet)\", \"references\", \"Data Sheet (sheet)\"))\n    check(\"xlsm: VBA macro extracted from vbaProject.bin\", \"RefreshSummary()\" in labels)\n    check(\"xlsm: macro → sheet link\", has_edge(\"RefreshSummary()\", \"uses_sheet\", \"Summary (sheet)\"))\n    check(\"xlsm: macro call chain\", has_edge(\"RefreshSummary()\", \"calls\", \"ReadData()\"))\n    check(\"xlsm: button → macro\", has_edge(\"Data Sheet (sheet)\", \"runs_macro\", \"RefreshSummary()\"))\n    check(\"xlsm: missing sheet flagged\", has_edge(\"ReadData()\", \"uses_sheet\", \"Ghost (missing sheet)\"))\n    check(\"csv: columns\", any(n[\"type\"] == \"column\" and n[\"label\"].startswith(\"Salary\") for n in g.nodes.values()))\n    check(\"sqlite: schema + FK\", has_edge(\"emp\", \"references\", \"dept\") and any(n[\"type\"] == \"database\" for n in g.nodes.values()))\n    check(\"email: mention; no person nodes from senders/recipients by default (personal data)\",\n          has_edge(\"mail.eml\", \"mentions\", \"SendTrainingPlan()\") and not has_edge(\"mail.eml\", \"sent_by\", \"HR\")\n          and not any(n.get(\"type\") == \"person\" for n in g.nodes.values()))\n    check(\"notebook: code cell function\", \"load_people()\" in labels)\n    check(\"archive: member code extracted\", \"purge_rows()\" in labels)\n    check(\"audio: sidecar transcript → mention\", has_edge(\"note.wav\", \"mentions\", \"PayrollService\"))\n    img = g.nodes.get(\"file:media/ocr_card.png\", {})\n    if ocr.available():\n        check(\"image OCR (local engine)\", \"KGRAPH\" in (Path(res[\"out\"]) / \"converted\" / \"media\" / \"ocr_card.png.md\").read_text(encoding=\"utf-8\").upper()\n              if (Path(res[\"out\"]) / \"converted\" / \"media\" / \"ocr_card.png.md\").exists() else False, img.get(\"ocr\", \"no text\"))\n    else:\n        check(\"image OCR (local engine)\", None, \"no OCR engine on this machine; agent vision covers images\")\n    check(\"image metadata\", img.get(\"width\", 0) > 0)\n    q = query(g, \"how does payroll compute net salary\")\n    check(\"query returns subgraph\", \"calculate_net\" in q)\n    check(\"path finds route\", \"hops\" in path(g, \"PayrollService\", \"apply_rate\"))\n    check(\"explain works\", \"Connections\" in explain(g, \"calculate_net\"))\n    check(\"report + html written\", (Path(res[\"out\"]) / \"GRAPH_REPORT.md\").exists() and (Path(res[\"out\"]) / \"graph.html\").exists())\n    res2 = build(corpus, quiet=True)\n    check(\"incremental rebuild uses cache\", res2[\"extracted\"] == 0 and res2[\"cached\"] == res[\"files\"])\n    _office_and_semantic_checks(tmp, check)\n    _coverage_checks(tmp, check)\n    _knowledge_checks(tmp, check)\n    _identity_checks(tmp, check)\n    _coverage_report_checks(tmp, check)\n    _validate_command_checks(tmp, check)\n    _truthful_status_checks(tmp, check)\n    _resolution_checks(tmp, check)\n    _upkeep_checks(tmp, check)\n    elapsed = time.time() - t0\n    if verbose:\n        caps = native.capabilities()\n        print(f\"kgraph selftest · {len(results)} checks · {elapsed:.1f}s · corpus {corpus}\")\n        print(f\"engines: windows_powershell={caps['windows_powershell']} tesseract={caps['tesseract']} ffmpeg={caps['ffmpeg']}\")\n        for name, status, detail in results:\n            print(f\"  {status:4}  {name}\" + (f\"  — {detail}\" if detail and status != \"PASS\" else \"\"))\n    failed = [r for r in results if r[1] == \"FAIL\"]\n    if verbose:\n        print(f\"RESULT: {'ALL PASSED' if not failed else f'{len(failed)} FAILED'} \"\n              f\"({sum(1 for r in results if r[1] == 'PASS')} pass, {sum(1 for r in results if r[1] == 'SKIP')} skip)\")\n    if not keep:\n        shutil.rmtree(tmp, ignore_errors=True)\n    return 1 if failed else 0\n\n\ndef _office_and_semantic_checks(tmp, check):\n    \"\"\"Tables/notes in Office files, garbled PDF text detection, and semantic plan copies/parts/merge.\"\"\"\n    from .extract_docs import extract_docx, extract_pptx\n    from .extract_more import garble_ratio\n    from .build import build\n    from . import semantic\n    P = 'xmlns:p=\"http://schemas.openxmlformats.org/presentationml/2006/main\" ' \\\n        'xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" ' \\\n        'xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"'\n    pptx = Path(tmp) / \"office\" / \"kpis.pptx\"\n    pptx.parent.mkdir(parents=True, exist_ok=True)\n    with zipfile.ZipFile(pptx, \"w\") as z:\n        z.writestr(\"ppt/slides/slide1.xml\", f'<p:sld {P}><p:cSld><p:spTree>'\n                   '<p:sp><p:nvSpPr><p:nvPr><p:ph type=\"title\"/></p:nvPr></p:nvSpPr><p:txBody><a:p><a:r><a:t>HR KPIs 2024</a:t></a:r></a:p></p:txBody></p:sp>'\n                   '<p:graphicFrame><a:graphic><a:graphicData><a:tbl>'\n                   '<a:tr><a:tc><a:txBody><a:p><a:r><a:t>Training coverage</a:t></a:r></a:p></a:txBody></a:tc>'\n                   '<a:tc><a:txBody><a:p><a:r><a:t>91%</a:t></a:r></a:p></a:txBody></a:tc></a:tr>'\n                   '</a:tbl></a:graphicData></a:graphic></p:graphicFrame></p:spTree></p:cSld></p:sld>')\n        z.writestr(\"ppt/slides/_rels/slide1.xml.rels\",\n                   '<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">'\n                   '<Relationship Id=\"rId2\" Type=\"notesSlide\" Target=\"../notesSlides/notesSlide1.xml\"/></Relationships>')\n        z.writestr(\"ppt/notesSlides/notesSlide1.xml\", f'<p:notes {P}><p:cSld><p:spTree><p:sp><p:txBody>'\n                   '<a:p><a:r><a:t>Target was 90%</a:t></a:r></a:p></p:txBody></p:sp></p:spTree></p:cSld></p:notes>')\n    t = extract_pptx(\"office/kpis.pptx\", str(pptx))[\"text\"]\n    check(\"pptx: table rows + speaker notes\", \"Training coverage | 91%\" in t and \"Target was 90%\" in t)\n    W = 'xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"'\n    docx = Path(tmp) / \"office\" / \"grid.docx\"\n    with zipfile.ZipFile(docx, \"w\") as z:\n        z.writestr(\"word/document.xml\", f'<w:document {W}><w:body><w:p><w:r><w:t>Annex 1</w:t></w:r></w:p>'\n                   '<w:tbl><w:tr><w:tc><w:p><w:r><w:t>Grade 4C</w:t></w:r></w:p></w:tc>'\n                   '<w:tc><w:p><w:r><w:t>0 years</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:body></w:document>')\n    check(\"docx: table kept as rows\", \"Grade 4C | 0 years\" in extract_docx(\"office/grid.docx\", str(docx))[\"text\"])\n    check(\"pdf: garbled text layer detected\",\n          garble_ratio(\"8 ��ƒ „„� ...† ‡ˆ ‰ Š‹ Œ Ž ‘’ “” •– —˜ ™š ›œ ž\") > 0.3\n          and garble_ratio('\\u0633\\u064a\\u0627\\u0633\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0628\\u0634\\u0631\\u064a\\u0629 \\u0644\\u0645\\u0631\\u0643\\u0632 \\u0627\\u0644\\u0646\\u0642\\u0644 \\u0627\\u0644\\u0645\\u062a\\u0643\\u0627\\u0645\\u0644 2026 Human Resources policy') == 0)\n    sem = Path(tmp) / \"semcorpus\"\n    (sem / \"a\").mkdir(parents=True, exist_ok=True)\n    (sem / \"b\").mkdir(parents=True, exist_ok=True)\n    (sem / \"a\" / \"same.md\").write_text(\"# Same\\nidentical policy text\", encoding=\"utf-8\")\n    (sem / \"b\" / \"same.md\").write_text(\"# Same\\nidentical policy text\", encoding=\"utf-8\")\n    (sem / \"a\" / \"big.md\").write_text(\"\\n\".join(f\"# Rule {i}\\nLeave rule {i}.\" for i in range(3000)), encoding=\"utf-8\")\n    out = Path(tmp) / \"semout\"\n    build(sem, out=out, quiet=True)\n    p = semantic.plan(sem, out, batch_chars=10**9, max_part_chars=20000)\n    ents = [e for b in p[\"batches\"] for e in b[\"files\"]]\n    parts = [e for e in ents if e.get(\"part\")]\n    check(\"semantic: identical copies planned once\", sum(1 for e in ents if e[\"rel\"].endswith(\"same.md\")) == 1\n          and any(e.get(\"copies\") for e in ents))\n    write_rec = {e[\"key\"]: {\"nodes\": [{\"label\": f\"Leave rule part {e.get('part', 0)}\", \"type\": \"requirement\"}],\n                            \"edges\": [], \"summary\": e[\"key\"]} for e in ents}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps({\"files\": write_rec}), encoding=\"utf-8\")\n    merged, problems = semantic.merge(out)\n    g2 = build(sem, out=out, quiet=True)\n    graph = json.loads((out / \"graph.json\").read_text(encoding=\"utf-8\"))\n    big = next((n for n in graph[\"nodes\"] if n[\"id\"] == \"file:a/big.md\"), {})\n    copy_b = next((n for n in graph[\"nodes\"] if n[\"id\"] == \"file:b/same.md\"), {})\n    check(\"semantic: long file split, parts merged, copies share result\",\n          len(parts) >= 2 and not problems and all(e[\"key\"] in big.get(\"summary\", \"\") for e in parts)\n          and bool(copy_b.get(\"summary\")) and g2[\"errors\"] == [])\n\n\ndef _coverage_checks(tmp, check):\n    \"\"\"Archives (tar.gz with nested document), unknown text files, unsupported/skipped reporting, Visio,\n    Excel charts, RTL bracket repair and the speech-confidence gate.\"\"\"\n    import tarfile\n    from .build import build\n    from .extract_docs import extract_xlsx\n    from .extract_more import extract_visio\n    from . import pdfparse, media\n    root = Path(tmp) / \"cov\"\n    (root / \"arc\").mkdir(parents=True, exist_ok=True)\n    inner = Path(tmp) / \"cov_inner\"\n    inner.mkdir(exist_ok=True)\n    (inner / \"leave-policy.md\").write_text(\"# Leave policy\\nAnnual leave is 30 working days.\", encoding=\"utf-8\")\n    with tarfile.open(root / \"arc\" / \"bundle.tar.gz\", \"w:gz\") as tf:\n        tf.add(inner / \"leave-policy.md\", arcname=\"docs/leave-policy.md\")\n    (root / \"notes.log2\").write_text(\"Plain text notes with an unknown extension about payroll cut-off.\", encoding=\"utf-8\")\n    (root / \"drawing.dwg\").write_bytes(b\"AC1027\" + bytes(range(256)) * 4)\n    import base64\n    att = base64.b64encode(\"# Overtime rule\\nOvertime needs director approval.\".encode(\"utf-8\")).decode()\n    (root / \"with_attachment.eml\").write_text(\n        \"From: HR <hr@example.org>\\nTo: Team <team@example.org>\\nSubject: Rules\\nMIME-Version: 1.0\\n\"\n        'Content-Type: multipart/mixed; boundary=\"B\"\\n\\n--B\\nContent-Type: text/plain\\n\\nSee attached rule.\\n'\n        '--B\\nContent-Type: text/markdown; name=\"overtime.md\"\\nContent-Disposition: attachment; filename=\"overtime.md\"\\n'\n        f\"Content-Transfer-Encoding: base64\\n\\n{att}\\n--B--\\n\", encoding=\"utf-8\")\n    (root / \"blob.bin9\").write_bytes(bytes(range(256)) * 8)\n    vsdx = root / \"flow.vsdx\"\n    NS = 'xmlns=\"http://schemas.microsoft.com/office/visio/2012/main\"'\n    with zipfile.ZipFile(vsdx, \"w\") as z:\n        z.writestr(\"visio/pages/page1.xml\", f'<PageContents {NS}><Shapes>'\n                   '<Shape ID=\"1\"><Text>Receive request</Text></Shape><Shape ID=\"2\"><Text>Approve request</Text></Shape>'\n                   '<Shape ID=\"3\"/></Shapes><Connects><Connect FromSheet=\"3\" FromCell=\"BeginX\" ToSheet=\"1\"/>'\n                   '<Connect FromSheet=\"3\" FromCell=\"EndX\" ToSheet=\"2\"/></Connects></PageContents>')\n    out = Path(tmp) / \"cov_out\"\n    res = build(root, out=out, quiet=True)\n    graph = json.loads((out / \"graph.json\").read_text(encoding=\"utf-8\"))\n    ids = {n[\"id\"] for n in graph[\"nodes\"]}\n    check(\"archive: tar.gz member extracted as a document\", any(i.startswith(\"file:arc/bundle.tar.gz!/\") and \"leave-policy\" in i for i in ids))\n    check(\"unknown extension: plain text sniffed and read\", \"file:notes.log2\" in ids)\n    check(\"email: attachment saved and extracted\", \"file:with_attachment.eml!/overtime.md\" in ids and not res[\"errors\"])\n    skipped = {s[\"rel\"]: s[\"reason\"] for s in json.loads((out / \"skipped.json\").read_text(encoding=\"utf-8\"))[\"skipped_files\"]}\n    report = (out / \"GRAPH_REPORT.md\").read_text(encoding=\"utf-8\")\n    check(\"skipped files reported with reasons\", \"drawing.dwg\" in skipped and \"blob.bin9\" in skipped\n          and \"Not read or only partly read\" in report and res[\"skipped\"] == 2)\n    vt = extract_visio(\"flow.vsdx\", str(vsdx))[\"text\"]\n    check(\"visio: shapes + connector flow\", \"Receive request → Approve request\" in vt)\n    xlsx = Path(tmp) / \"cov_chart.xlsx\"\n    S = 'xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"'\n    C = 'xmlns:c=\"http://schemas.openxmlformats.org/drawingml/2006/chart\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"'\n    RELS = 'xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"'\n    with zipfile.ZipFile(xlsx, \"w\") as z:\n        z.writestr(\"xl/workbook.xml\", f'<workbook {S}><sheets><sheet name=\"Dash\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>')\n        z.writestr(\"xl/_rels/workbook.xml.rels\", f'<Relationships {RELS}><Relationship Id=\"rId1\" Target=\"worksheets/sheet1.xml\"/></Relationships>')\n        z.writestr(\"xl/worksheets/sheet1.xml\", f'<worksheet {S}><sheetData/><drawing r:id=\"rId1\"/></worksheet>')\n        z.writestr(\"xl/worksheets/_rels/sheet1.xml.rels\", f'<Relationships {RELS}><Relationship Id=\"rId1\" Target=\"../drawings/drawing1.xml\"/></Relationships>')\n        z.writestr(\"xl/drawings/drawing1.xml\", f'<xdr:wsDr xmlns:xdr=\"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\" {C}>'\n                   '<xdr:graphicFrame><a:graphic><a:graphicData><c:chart r:id=\"rId1\"/></a:graphicData></a:graphic></xdr:graphicFrame></xdr:wsDr>')\n        z.writestr(\"xl/drawings/_rels/drawing1.xml.rels\", f'<Relationships {RELS}><Relationship Id=\"rId1\" Target=\"../charts/chart1.xml\"/></Relationships>')\n        z.writestr(\"xl/charts/chart1.xml\", f'<c:chartSpace {C}><c:chart><c:plotArea><c:barChart><c:ser>'\n                   '<c:tx><c:v>Headcount</c:v></c:tx><c:cat><c:strRef><c:strCache><c:pt idx=\"0\"><c:v>Female</c:v></c:pt><c:pt idx=\"1\"><c:v>Male</c:v></c:pt></c:strCache></c:strRef></c:cat>'\n                   '<c:val><c:numRef><c:numCache><c:pt idx=\"0\"><c:v>480</c:v></c:pt><c:pt idx=\"1\"><c:v>766</c:v></c:pt></c:numCache></c:numRef></c:val>'\n                   '</c:ser></c:barChart></c:plotArea></c:chart></c:chartSpace>')\n    xt = extract_xlsx(\"cov_chart.xlsx\", str(xlsx))[\"text\"]\n    check(\"xlsx: chart series extracted\", \"Series Headcount: Female=480; Male=766\" in xt)\n    check(\"pdf: inside-out RTL brackets repaired\",\n          pdfparse._fix_bracket_pairs('\\u0627\\u0644\\u0641\\u0635\\u0644 )10( \\u0648\\u0627\\u0644\\u0641\\u0635\\u0644 )11(') == '\\u0627\\u0644\\u0641\\u0635\\u0644 (10) \\u0648\\u0627\\u0644\\u0641\\u0635\\u0644 (11)'\n          and pdfparse._fix_bracket_pairs('\\u0627\\u0644\\u0645\\u0627\\u062f\\u0629 (12) \\u0645\\u0646') == '\\u0627\\u0644\\u0645\\u0627\\u062f\\u0629 (12) \\u0645\\u0646')\n    check(\"media: low-confidence dictation is gated\", 0 < media.MIN_DICTATION_CONFIDENCE <= 0.5)\n    from . import watch\n    fps12, n12 = watch.frame_budget(12, 80)\n    fps300, n300 = watch.frame_budget(300, 80)\n    fpsf, nf = watch.frame_budget(10, 100, focused=True)\n    times, _f, focused = watch.frame_times(120, start=30, end=60, max_frames=100)\n    check(\"watch: duration-scaled frame budgets (full, long, focused)\",\n          n12 == 12 and fps12 <= 2 and n300 == 80 and fpsf == 2.0 and nf == 20\n          and focused and times[0] >= 30 and times[-1] <= 60)\n    vtt = ('WEBVTT\\n\\n00:00:01.000 --> 00:00:02.000\\n\\u0645\\u0631\\u062d\\u0628\\u0627\\n\\n00:00:02.000 --> 00:00:03.000\\n\\u0645\\u0631\\u062d\\u0628\\u0627 \\u0628\\u0643\\u0645\\n\\n'\n           '00:00:03.000 --> 00:00:04.000\\n\\u0645\\u0631\\u062d\\u0628\\u0627 \\u0628\\u0643\\u0645\\n\\n1\\n00:00:05,000 --> 00:00:06,500\\n<i>Second line</i>\\n')\n    segs = watch.parse_captions(vtt)\n    check(\"watch: captions parsed with rolling duplicates collapsed (VTT + SRT)\",\n          [s[\"text\"] for s in segs] == ['\\u0645\\u0631\\u062d\\u0628\\u0627 \\u0628\\u0643\\u0645', \"Second line\"] and segs[0][\"end\"] == 4.0)\n    check(\"mp4: fragmented streams rebuilt and merged into a plain MP4\", _fmp4_roundtrip(Path(tmp)))\n    _workflow_checks(Path(tmp), check)\n\n\ndef _workflow_checks(tmp, check):\n    \"\"\"Checks for the fixes from a real 500-file analysis session: identical copies, exclusions, privacy option,\n    readable report/parts, status, Arabic search folding, page-selective OCR cache, RTL percent order.\"\"\"\n    import json\n    import shutil\n    from . import build as build_mod, ocr, pdfparse, workflow\n    from .graph import Graph\n    from .util import bare, fold_text, tokens\n\n    root = tmp / \"wf\"\n    (root / \"a\" / \"evidence\").mkdir(parents=True)\n    (root / \"b\").mkdir(parents=True)\n    doc = \"# Remote work policy\\n\\n## 1. Scope\\nRemote work is limited to two days per month.\\n\\n## 2. Approval\\nThe HR Committee approves exceptions.\\n\"\n    (root / \"a\" / \"policy.md\").write_text(doc, encoding=\"utf-8\")\n    (root / \"b\" / \"policy copy.md\").write_text(doc, encoding=\"utf-8\")\n    (root / \"a\" / \"evidence\" / \"policy (old).md\").write_text(doc, encoding=\"utf-8\")\n    (root / \"Results\").mkdir()\n    (root / \"Results\" / \"notes.md\").write_text(\"# My analysis notes\\n\", encoding=\"utf-8\")\n    eml = (\"From: HR Team <hr@example.org>\\nTo: A Person <a@example.org>, B Person <b@example.org>\\n\"\n           \"Subject: Policy update\\nDate: Mon, 1 Sep 2026 10:00:00 +0000\\n\\nPlease read the policy.\\n\")\n    (root / \"b\" / \"update.eml\").write_text(eml, encoding=\"utf-8\")\n    out = root / \"Results\" / \"kgraph-out\"\n    res = build_mod.build(root, out=out, quiet=True, exclude=[\"Results/\"])\n    g = Graph.load(out / \"graph.json\")\n    rels = {n.get(\"source_file\") for n in g.nodes.values()}\n    stats = json.loads((out / \"build_stats.json\").read_text(encoding=\"utf-8\"))\n    copy_sections = [nid for nid in g.nodes if nid.startswith(\"b/policy copy.md::\")]\n    check(\"build: identical copies extracted once and re-pointed at their own paths\",\n          stats.get(\"identical_copies_reused\") == 2 and copy_sections\n          and g.nodes.get(\"file:b/policy copy.md\", {}).get(\"label\") == \"policy copy.md\")\n    check(\"build: --exclude and output folder kept out of the corpus (nothing written to the source)\",\n          \"Results/notes.md\" not in rels and not any(str(r).startswith(\"Results/\") for r in rels if r)\n          and build_mod.saved_options(out).get(\"exclude\") == [\"Results/\"] and not (root / \".kgraphignore\").exists())\n    dup = json.loads((out / \"duplicates.json\").read_text(encoding=\"utf-8\"))\n    check(\"build: duplicates.json names a canonical copy per group\",\n          dup[\"groups\"] and dup[\"groups\"][0][\"copies\"] == 3 and dup[\"groups\"][0][\"canonical\"] == \"a/policy.md\")\n    people = build_mod.build(root, out=root / \"people-out\", quiet=True, exclude=[\"Results/\"], people=True)\n    gp = Graph.load(Path(people[\"out\"]) / \"graph.json\")\n    check(\"email: person nodes only with --people\",\n          any(n.get(\"type\") == \"person\" for n in gp.nodes.values())\n          and not any(n.get(\"type\") == \"person\" for n in g.nodes.values())\n          and g.nodes[\"file:b/update.eml\"].get(\"recipients\") == 2)\n    shutil.rmtree(root / \"people-out\", ignore_errors=True)\n    st = workflow.status(out / \"graph.json\")\n    check(\"status: reports unfinished steps (semantic pass not run → not complete)\",\n          st[\"complete\"] is False and st[\"semantic\"][\"missing\"] >= 1 and \"Semantic pass\" in workflow.render_status(st))\n    report = (out / \"GRAPH_REPORT.md\").read_text(encoding=\"utf-8\")\n    from .report import estimate_tokens, REPORT_TOKEN_BUDGET\n    check(\"report: within one-read budget, appendix written\",\n          estimate_tokens(report) <= REPORT_TOKEN_BUDGET and (out / \"report\" / \"communities.md\").is_file()\n          and (out / \"report\" / \"needs_visual_review.md\").is_file())\n    long_text = \"\".join(f\"<!-- page {i} -->\\n\" + ('\\u0646\\u0635 \\u0639\\u0631\\u0628\\u064a \\u0637\\u0648\\u064a\\u0644 \\u0644\\u0644\\u0627\\u062e\\u062a\\u0628\\u0627\\u0631 ' * 40 + \"\\n\") * 6 for i in range(1, 40))\n    parts = workflow.split_parts(long_text, 20000)\n    check(\"read: long converted text split at page boundaries into parts that fit one read\",\n          len(parts) > 2 and all(sum(len(l.encode(\"utf-8\")) for _n, l in p) <= 20000 for p in parts)\n          and all(p[0][1].startswith(\"<!-- page\") for p in parts))\n    check(\"search: Arabic diacritics/letter variants folded\",\n          fold_text('\\u062a\\u064f\\u062d\\u062f\\u064e\\u0651\\u062b \\u0627\\u0644\\u0623\\u062f\\u0627\\u0621') == fold_text('\\u062a\\u062d\\u062f\\u062b \\u0627\\u0644\\u0627\\u062f\\u0627\\u0621') and bare('\\u0625\\u0637\\u0627\\u0631') == bare('\\u0627\\u0637\\u0627\\u0631')\n          and '\\u062a\\u062d\\u062f\\u062b' in tokens('\\u0633\\u0648\\u0641 \\u062a\\u064f\\u062d\\u062f\\u064e\\u0651\\u062b'))\n    # page-selective OCR: the second request reads only the page it does not have yet\n    fake_pdf = tmp / \"scan.pdf\"\n    fake_pdf.write_bytes(b\"%PDF-1.4 fake scanned document for cache logic\")\n    calls = []\n\n    def fake_windows(path, max_pages, save_dir=None, pages=None):\n        calls.append(list(pages or []))\n        return {\"engine\": \"windows.media.ocr\", \"languages\": \"\", \"page_count\": 9,\n                \"pages\": [{\"page\": p, \"text\": f\"page {p} text with enough words\", \"quality\": 0.9, \"image\": \"\", \"rotated\": 0}\n                          for p in (pages or [])]}\n\n    saved = (ocr._windows_ocr, ocr.native.windows_powershell, ocr._languages)\n    try:\n        ocr._windows_ocr = fake_windows\n        ocr.native.windows_powershell = lambda: \"powershell\"\n        ocr._languages = lambda: \"\"\n        cache = tmp / \"ocrcache\"\n        a = ocr.ocr_file(fake_pdf, cache, pages=[2, 5])\n        b = ocr.ocr_file(fake_pdf, cache, pages=[5, 7])\n        c = ocr.ocr_file(fake_pdf, cache, pages=[2, 7])\n    finally:\n        ocr._windows_ocr, ocr.native.windows_powershell, ocr._languages = saved\n    check(\"ocr: only pages that need OCR are read; cache adds missing pages only\",\n          calls == [[2, 5], [7]] and [p[\"page\"] for p in b[\"pages\"]] == [5, 7] and [p[\"page\"] for p in c[\"pages\"]] == [2, 7]\n          and [p[\"page\"] for p in a[\"pages\"]] == [2, 5])\n    seq = ['\\u0629', \" \", \"1\", \"9\", \"%\", '\\u060c']\n    check(\"pdf: RTL percent keeps logical order (91%)\",\n          pdfparse._restore_ltr_runs(seq) == '\\u0629 91%\\u060c' and pdfparse._restore_ltr_runs([\"%\", \"1\", \"9\", \" \", '\\u0645']) == '91% \\u0645')\n    # a long file read in parts before part counts were stored: plan and status must agree it is done\n    from . import semantic\n    lo = tmp / \"legacy-out\"\n    (lo / \"converted\").mkdir(parents=True)\n    (lo / \"converted\" / \"long.pdf.md\").write_text((\"x\" * 99 + \"\\n\") * 6100, encoding=\"utf-8\")  # 5 parts at 150 kB; 4 were read\n    (lo / \"manifest.json\").write_text(json.dumps({\"long.pdf\": {\"size\": 1, \"mtime\": 0, \"sha\": \"abc\", \"category\": \"pdf\"}}),\n                                      encoding=\"utf-8\")\n    (lo / \"cache\" / \"semantic\").mkdir(parents=True)\n    (lo / \"cache\" / \"semantic\" / \"abc.json\").write_text(json.dumps({\"parts\": [\"p1\", \"p2\", \"p3\", \"p4\", \"s1\"], \"nodes\": []}),\n                                                         encoding=\"utf-8\")\n    legacy_plan = semantic.plan(tmp, lo, reuse=False)\n    check(\"semantic-plan: legacy split reading counted as complete, like kg status (no extra part requested)\",\n          not any(f[\"rel\"] == \"long.pdf\" for b in legacy_plan[\"batches\"] for f in b[\"files\"]))\n\n\ndef _knowledge_checks(tmp, check):\n    \"\"\"Cowork edition: find the latest saved knowledge inside the chosen folder (key file or another edition's\n    output, any folder name), continue it without re-reading, keep it out of the corpus; else start from scratch.\"\"\"\n    import json\n    import os\n    import shutil\n    from . import build as build_mod, knowledge, native, ocr\n    from .graph import Graph\n    from .util import find_graph\n\n    k = tmp / \"kn\"\n    (k / \"docs\").mkdir(parents=True)\n    (k / \"docs\" / \"policy.md\").write_text(\"# Leave policy\\n\\nAnnual leave needs approval.\\n\", encoding=\"utf-8\")\n    (k / \"docs\" / \"plan.md\").write_text(\"# Workforce plan\\n\\nSee [policy](policy.md).\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    check(\"knowledge: empty folder → nothing found, start from scratch in <folder>/kgraph-out\",\n          knowledge.discover(k) == [] and knowledge.locate(k) is None\n          and build_mod.out_dir_for(k) == (k / \"kgraph-out\").resolve()\n          and \"start from scratch\" in knowledge.render(k, [], None).lower())\n    # knowledge made elsewhere (e.g. Claude Code with --out outside the folder), without the key file\n    (k / \"Results\").mkdir()\n    (k / \"Results\" / \"00_README.md\").write_text(\"# Results index\\n\", encoding=\"utf-8\")  # the user's own notes\n    ext = tmp / \"elsewhere\" / \"KB\"\n    first = build_mod.build(k, out=ext, quiet=True)\n    key = json.loads((ext / knowledge.KEY_FILE).read_text(encoding=\"utf-8\"))\n    check(\"knowledge: every build writes KGRAPH_KNOWLEDGE.json (status, original folder)\",\n          key.get(\"kgraph_knowledge\") == 1 and key.get(\"status\", {}).get(\"files\") == first[\"files\"]\n          and key.get(\"root_original\") == str(k.resolve()))\n    (ext / knowledge.KEY_FILE).unlink()  # as written by an edition that has no key file\n    kb = k / \"Results\" / \"My Knowledge Base\"\n    shutil.copytree(ext, kb)\n    knowledge.forget()\n    rows = knowledge.discover(k)\n    check(\"knowledge: output of another edition found by graph.json + manifest.json, under any folder name\",\n          len(rows) == 1 and rows[0][\"out\"] == kb.resolve() and rows[0][\"root\"] is not None and rows[0][\"has_key\"] is False)\n    # an older copy of the same knowledge: the latest one must win\n    old = k / \"old-knowledge\"\n    shutil.copytree(kb, old)\n    for f in old.iterdir():\n        if f.is_file():\n            os.utime(f, (1_000_000_000, 1_000_000_000))\n    knowledge.forget()\n    check(\"knowledge: the most recently updated knowledge for the folder is chosen\",\n          knowledge.locate(k) == kb.resolve() and find_graph(str(k)) == kb.resolve() / \"graph.json\")\n    docs = [p.name for p in knowledge.deliverables(kb, k)]\n    check(\"knowledge: analysis documents saved next to it are listed (README first)\",\n          docs[:1] == [\"00_README.md\"] and \"Latest knowledge for this folder\" in knowledge.render(k, knowledge.discover(k), kb.resolve()))\n    shutil.rmtree(old)\n    knowledge.forget()\n    again = build_mod.build(k, quiet=True)\n    g = Graph.load(kb / \"graph.json\")\n    rels = {n.get(\"source_file\") for n in g.nodes.values() if n.get(\"source_file\")}\n    check(\"knowledge: build continues the found knowledge (nothing re-read, no new kgraph-out, history kept)\",\n          Path(again[\"out\"]) == kb.resolve() and again[\"extracted\"] == 0 and again[\"cached\"] == first[\"files\"]\n          and not (k / \"kgraph-out\").exists() and any((kb / \"history\").iterdir())\n          and (kb / knowledge.KEY_FILE).is_file())\n    check(\"knowledge: saved knowledge folders are never read as documents\",\n          \"Results/00_README.md\" in rels\n          and not any(str(r).startswith((\"Results/My Knowledge Base\", \"old-knowledge\")) for r in rels))\n    saved = native.windows_powershell\n    try:\n        native.windows_powershell = lambda: None\n        win_hit = ocr._valid_hit({\"engine\": \"windows.media.ocr\", \"languages\": \"ar,en\", \"pages\": []})\n    finally:\n        native.windows_powershell = saved\n    check(\"ocr: text read by Windows OCR is reused in a sandbox without that engine\", win_hit is True)\n    knowledge.forget()\n\n\ndef _identity_checks(tmp, check):\n    \"\"\"Files are known by content (sha256), not by name or place: renamed / moved files keep their knowledge,\n    reviews and community names; answers check their sources' content now; edits are caught even when size and\n    modified time were kept; files moved out of the folder are found in --also-search folders.\"\"\"\n    import json\n    import os\n    import shutil\n    from . import build as build_mod, fresh, knowledge\n    from .graph import Graph\n    from .workflow import mark_reviewed\n\n    k = tmp / \"ident\"\n    (k / \"docs\").mkdir(parents=True)\n    outside = tmp / \"ident_archive\"\n    outside.mkdir()\n    (k / \"docs\" / \"leave.md\").write_text(\"# Leave policy\\n\\nAnnual leave needs manager approval. See [plan](plan.md).\\n\", encoding=\"utf-8\")\n    (k / \"docs\" / \"plan.md\").write_text(\"# Workforce plan\\n\\nHiring follows the approved budget.\\n\", encoding=\"utf-8\")\n    (k / \"notes.txt\").write_text(\"Payroll cut-off is the 20th of each month.\\n\", encoding=\"utf-8\")\n    (k / \"old.txt\").write_text(\"Archived note about the 2019 training calendar.\\n\", encoding=\"utf-8\")\n    (k / \"staff.csv\").write_text(\"Unit,Positions\\nHR,12\\nFinance,9\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    first = build_mod.build(k, quiet=True, also_search=[str(outside)])\n    out = Path(first[\"out\"])\n    mark_reviewed(out / \"graph.json\", [\"docs/leave.md\"], note=\"viewed\")\n    g = Graph.load(out / \"graph.json\")\n    cid = g.nodes[\"file:docs/leave.md\"][\"community\"]\n    anchor = build_mod.set_label(out / \"graph.json\", cid, \"Leave rules\")\n\n    # rename one file and move another into a new subfolder\n    (k / \"docs\" / \"leave.md\").rename(k / \"docs\" / \"Leave policy (approved copy).md\")\n    (k / \"archive\" / \"2026\").mkdir(parents=True)\n    shutil.move(str(k / \"docs\" / \"plan.md\"), str(k / \"archive\" / \"2026\" / \"plan.md\"))\n    shutil.move(str(k / \"staff.csv\"), str(k / \"archive\" / \"2026\" / \"staff 2026.csv\"))\n    text_old = \"src=docs/leave.md:L1 and src=docs/plan.md:L1\"\n    rows, _root = fresh.check(out, fresh.sources_in(text_old, json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))))\n    states = {r: st for r, st, _d in rows}\n    where = {r: d for r, _st, d in rows}\n    check(\"identity: an answer naming a renamed/moved file finds it by content and gives its new path\",\n          states == {\"docs/leave.md\": \"moved\", \"docs/plan.md\": \"moved\"}\n          and where[\"docs/leave.md\"] == \"docs/Leave policy (approved copy).md\"\n          and where[\"docs/plan.md\"] == \"archive/2026/plan.md\")\n    knowledge.forget()\n    rows = knowledge.discover(k)\n    check(\"identity: knowledge is still recognised after renaming/moving files (matched by content)\",\n          len(rows) == 1 and rows[0][\"root\"] is not None and knowledge.locate(k) == out.resolve()\n          and rows[0][\"moved\"] >= 1 and \"recognised by content\" in knowledge.render(k, rows, out.resolve()))\n    second = build_mod.build(k, quiet=True)\n    stats = json.loads((out / \"build_stats.json\").read_text(encoding=\"utf-8\"))\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    check(\"identity: build re-points renamed/moved files without re-reading them\",\n          Path(second[\"out\"]) == out.resolve() and second[\"moved\"] == 3 and second[\"extracted\"] == 0\n          and stats[\"reused_after_move\"] == 3 and \"docs/Leave policy (approved copy).md\" in manifest\n          and \"docs/leave.md\" not in manifest and \"archive/2026/plan.md\" in manifest)\n    conv_new = out / \"converted\" / \"archive/2026/staff 2026.csv.md\"\n    check(\"identity: converted text follows a moved file (new path, header updated, no stale copy)\",\n          conv_new.is_file() and \"from archive/2026/staff 2026.csv -->\" in conv_new.read_text(encoding=\"utf-8\")\n          and not (out / \"converted\" / \"staff.csv.md\").exists())\n    review = json.loads((out / \"review.json\").read_text(encoding=\"utf-8\"))\n    g2 = Graph.load(out / \"graph.json\")\n    new_anchor = anchor.replace(\"docs/leave.md\", \"docs/Leave policy (approved copy).md\")\n    labels = json.loads((out / \"labels.json\").read_text(encoding=\"utf-8\"))\n    comm = (g2.communities or {}).get(str(g2.nodes.get(new_anchor, {}).get(\"community\")), {})\n    check(\"identity: visual-review records and community names follow the file by content\",\n          \"docs/Leave policy (approved copy).md\" in review and \"docs/leave.md\" not in review\n          and labels.get(new_anchor) == \"Leave rules\" and comm.get(\"label\") == \"Leave rules\" and comm.get(\"named\"))\n\n    # the rare case: content edited, size and modified time kept\n    p = k / \"notes.txt\"\n    st = p.stat()\n    p.write_text(\"Payroll cut-off is the 25th of each month.\\n\", encoding=\"utf-8\")\n    os.utime(p, ns=(st.st_atime_ns, st.st_mtime_ns))\n    same = p.stat().st_size == st.st_size and p.stat().st_mtime_ns == st.st_mtime_ns\n    ans = fresh.annotate(\"NODE notes.txt [src=notes.txt:L1]\", out / \"graph.json\")\n    check(\"identity: an answer flags a source whose content changed even with the same size and modified time\",\n          same and \"CHANGED since the last build: notes.txt\" in ans)\n    quick = build_mod.build(k, quiet=True, verify_days=0)\n    verified = build_mod.build(k, quiet=True, verify=True)\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    from .util import sha256_file\n    check(\"identity: `build --verify` fingerprints every file and re-reads the silently edited one\",\n          quick[\"extracted\"] == 0 and not quick[\"full_content_check\"]\n          and verified[\"full_content_check\"] and verified[\"extracted\"] == 1\n          and manifest[\"notes.txt\"][\"sha\"] == sha256_file(p)\n          and \"unchanged\" in fresh.annotate(\"src=notes.txt\", out / \"graph.json\"))\n    st_path = out / \"build_stats.json\"\n    bs = json.loads(st_path.read_text(encoding=\"utf-8\"))\n    bs[\"verified_epoch\"] = 0\n    st_path.write_text(json.dumps(bs), encoding=\"utf-8\")\n    periodic = build_mod.build(k, quiet=True, verify_days=7)\n    check(\"identity: a full content check runs automatically when the last one is older than verify_days\",\n          periodic[\"full_content_check\"] and json.loads((out / \"build_options.json\").read_text(encoding=\"utf-8\"))[\"verify_days\"] == 7)\n\n    # a file moved out of the folder: found in the remembered --also-search folder\n    shutil.move(str(k / \"old.txt\"), str(outside / \"old.txt\"))\n    ans = fresh.annotate(\"src=old.txt:L1\", out / \"graph.json\")\n    left = build_mod.build(k, quiet=True)\n    stats = json.loads((out / \"build_stats.json\").read_text(encoding=\"utf-8\"))\n    check(\"identity: a file moved outside the folder is found by content in --also-search folders\",\n          \"MOVED OUTSIDE the folder\" in ans and str(outside / \"old.txt\") in ans\n          and left[\"left_folder_found\"] == 1 and stats[\"left_folder_found\"][0][\"was\"] == \"old.txt\")\n\n    # every file replaced: nothing matches, and the message says the default knowledge folder is continued\n    z = tmp / \"ident2\"\n    z.mkdir()\n    (z / \"a.txt\").write_text(\"first version of a note about approvals\\n\", encoding=\"utf-8\")\n    zb = build_mod.build(z, quiet=True)\n    (z / \"a.txt\").unlink()\n    (z / \"b.txt\").write_text(\"a completely different note about recruitment channels\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    zrows = knowledge.discover(z)\n    msg = knowledge.render(z, zrows, knowledge.locate(z))\n    check(\"identity: when no file matches, the message says this folder's own knowledge folder is continued\",\n          zrows and zrows[0][\"root\"] is None and \"continues it\" in msg and \"starts a new\" not in msg\n          and build_mod.out_dir_for(z) == Path(zb[\"out\"]).resolve())\n    knowledge.forget()\n\n\ndef _coverage_report_checks(tmp, check):\n    \"\"\"2.2: nothing disappears in silence. Folders that are not entered are reported (and build-output names only\n    count as build output where they look like it), and semantic records that lose nodes or point at undeclared\n    endpoints are named per file instead of being swallowed by a 'merged N results' line.\"\"\"\n    import json\n    from . import knowledge, semantic\n    from .build import build\n    from .workflow import status, render_status\n\n    k = tmp / \"cov\"\n    (k / \"docs\" / \"bin\").mkdir(parents=True)          # 'bin' inside documents: ordinary content\n    (k / \"bin\").mkdir()                                # 'bin' at the project root: build output\n    (k / \"src\").mkdir()\n    (k / \"pyproject.toml\").write_text(\"[project]\\nname='x'\\n\", encoding=\"utf-8\")\n    (k / \"docs\" / \"bin\" / \"notes.md\").write_text(\"# Launcher notes\\n\\nHow the CLI starts.\\n\", encoding=\"utf-8\")\n    (k / \"bin\" / \"auto.cmd\").write_text(\"@echo off\\r\\necho hi\\r\\n\", encoding=\"utf-8\")\n    (k / \"bin\" / \"tool.exe.txt\").write_text(\"build output\\n\", encoding=\"utf-8\")\n    (k / \"src\" / \"app.py\").write_text(\"def run():\\n    return 1\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    res = build(k, quiet=True)\n    out = Path(res[\"out\"])\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    skipped = json.loads((out / \"skipped.json\").read_text(encoding=\"utf-8\"))\n    report = (out / \"GRAPH_REPORT.md\").read_text(encoding=\"utf-8\")\n    folders = {d[\"rel\"]: d for d in skipped.get(\"skipped_folders\", [])}\n    check(\"coverage: a build-output name deep inside content is read, not skipped by name\",\n          \"docs/bin/notes.md\" in manifest and res[\"skipped_dirs\"] == 1)\n    check(\"coverage: a folder that was not entered is reported with its file count\",\n          \"bin\" in folders and folders[\"bin\"][\"files\"] == 2 and \"--include-dir\" in folders[\"bin\"][\"reason\"]\n          and \"folder not entered\" in report and \"bin\" in report)\n    st = status(out / \"graph.json\")\n    check(\"coverage: status counts folders that were not entered and says how to read them\",\n          st[\"build\"][\"skipped_dirs\"] == 1 and st[\"build\"][\"skipped_dir_files\"] == 2\n          and any(\"--include-dir\" in s for s in st[\"next_steps\"])\n          and \"folders not entered\" in render_status(st))\n    res2 = build(k, quiet=True, include_dirs=[\"bin\"])\n    manifest2 = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    opts = json.loads((out / \"build_options.json\").read_text(encoding=\"utf-8\"))\n    res3 = build(k, quiet=True)  # remembered\n    check(\"coverage: --include-dir reads the folder and is remembered\",\n          \"bin/auto.cmd\" in manifest2 and res2[\"skipped_dirs\"] == 0 and opts[\"include_dirs\"] == [\"bin\"]\n          and res3[\"skipped_dirs\"] == 0)\n\n    # semantic records: dropped nodes and undeclared endpoints are named\n    semantic.plan(k, out_dir=out)\n    recs = {\"files\": {\"docs/bin/notes.md\": {\n        \"summary\": \"Launcher notes\",\n        \"nodes\": [{\"id\": \"n1\", \"type\": \"concept\"},                      # no label: unusable\n                  {\"label\": \"CLI launcher\", \"type\": \"concept\"}],\n        \"edges\": [{\"source\": \"CLI launcher\", \"target\": \"finding:F-04\", \"relation\": \"supports\",\n                   \"confidence\": \"MAYBE\", \"score\": \"high\"}]}}}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps(recs), encoding=\"utf-8\")\n    checked, vproblems, vnotes = semantic.validate_files([out / \"semantic\" / \"results\" / \"batch_1.json\"], out)\n    joined = \" | \".join(vproblems)\n    check(\"semantic: a node without a label, a bad confidence and a non-numeric score are all reported\",\n          checked == 1 and \"without a usable\" in joined and \"n1\" in joined and \"MAYBE\" in joined\n          and \"score is not a number\" in joined)\n    check(\"semantic: an edge endpoint that the record never declares is reported\",\n          \"not declared as nodes\" in joined and \"finding:F-04\" in joined)\n    merged, mproblems = semantic.merge(out)\n    check(\"semantic: merge reports the same problems per file instead of merging silently\",\n          merged == 1 and any(\"without a usable\" in p for p in mproblems)\n          and any(\"not declared as nodes\" in p for p in mproblems))\n    knowledge.forget()\n\n\ndef _validate_command_checks(tmp, check):\n    \"\"\"`kg semantic-validate <folder>` must work exactly as the skill writes it, must judge every result file by\n    its own map, and must only fail on things the merge would actually reject.\"\"\"\n    import json\n    import os\n    from . import knowledge, semantic\n    from .build import build\n    from .cli import main\n\n    k = tmp / \"validate_cmd\"\n    k.mkdir()\n    (k / \"policy.md\").write_text(\"# Policy\\n\\nLeave needs approval.\\n\", encoding=\"utf-8\")\n    long_body = \"\".join(f\"## Part {i}\\n\\nRule {i} applies to every request.\\n\\n\" for i in range(200))\n    (k / \"manual.md\").write_text(long_body, encoding=\"utf-8\")\n    knowledge.forget()\n    out = Path(build(k, quiet=True)[\"out\"])\n    plan = semantic.plan(k, out_dir=out, max_part_chars=6000)\n    keys = {f[\"key\"] for b in plan[\"batches\"] for f in b[\"files\"]}\n    check(\"validate: the long document was planned in parts (precondition)\", \"manual.md#p1\" in keys)\n\n    recs = {\"files\": {\n        \"policy.md\": {\"summary\": \"policy\", \"nodes\": [{\"label\": \"Approval rule\"}], \"edges\": []},\n        \"manual.md\": {\"summary\": \"whole manual read in one go\",      # deliberate: one record for every part\n                      \"nodes\": [{\"label\": \"Request rules\"}], \"edges\": []}}}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps(recs), encoding=\"utf-8\")\n\n    paths, found_out = semantic.result_files_for(k)\n    check(\"validate: a project folder resolves to its own knowledge folder and result files\",\n          len(paths) == 1 and Path(found_out) == out\n          and semantic.result_files_for(out)[0] == paths)\n    checked, problems, notes = semantic.validate_files(paths, out)\n    check(\"validate: one record for a file the plan split is a note, not a problem — the merge accepts it\",\n          checked == 2 and not problems and any(\"manual.md\" in n for n in notes))\n    rc = main([\"semantic-validate\", str(k)])\n    check(\"validate: `kg semantic-validate <folder>` runs as documented and succeeds\", rc == 0)\n\n    # a result file named on its own carries its own map: results live in <knowledge folder>/semantic/results/\n    result = out / \"semantic\" / \"results\" / \"batch_1.json\"\n    other = tmp / \"validate_elsewhere\"\n    (other / \"sub\").mkdir(parents=True)\n    (other / \"sub\" / \"other.md\").write_text(\"# Other\\n\\nUnrelated project.\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    build(other, quiet=True)                   # a different project, with its own knowledge, to stand in the way\n    check(\"validate: a result file resolves to the knowledge folder it sits in\",\n          Path(semantic.knowledge_dir_of(result)) == out.resolve()\n          and semantic.knowledge_dir_of(k / \"policy.md\") is None)\n    cwd = os.getcwd()\n    try:\n        os.chdir(other)                        # the folder the shell is in must not decide which map is used\n        rc_file = main([\"semantic-validate\", str(result)])\n    finally:\n        os.chdir(cwd)\n    check(\"validate: a single result file is checked against its own map, not the folder the shell is in\",\n          rc_file == 0)\n    _, fproblems, fnotes = semantic.validate_files([result], semantic.knowledge_dir_of(result))\n    check(\"validate: checking one file still applies the plan checks (no silent 'OK')\",\n          not fproblems and any(\"manual.md\" in n for n in fnotes))\n    knowledge.forget()\n    merged, mproblems = semantic.merge(out)\n    check(\"validate: what validate passes, merge accepts\", merged == 2 and not mproblems)\n    knowledge.forget()\n\n\ndef _truthful_status_checks(tmp, check):\n    \"\"\"2.1/2.2: `kg status` counts every readable document and never calls a restricted build 'complete: yes'.\"\"\"\n    import json\n    from . import knowledge, semantic\n    from .build import build\n    from .workflow import status, render_status\n\n    k = tmp / \"truth\"\n    (k / \"notes\").mkdir(parents=True)\n    for i in range(3):\n        (k / \"notes\" / f\"n{i}.md\").write_text(f\"# Note {i}\\n\\nLeave needs approval {i}.\\n\", encoding=\"utf-8\")\n    (k / \"log.jsonl\").write_text('{\"event\": \"start\"}\\n', encoding=\"utf-8\")\n    (k / \"app.py\").write_text(\"def run():\\n    return 1\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    build(k, quiet=True)\n    out = Path(build(k, quiet=True)[\"out\"])\n    st = status(out / \"graph.json\")\n    check(\"status: plain-text documents count as readable, not 0/0\",\n          st[\"semantic\"][\"eligible_contents\"] == 4 and st[\"semantic\"][\"merged\"] == 0 and not st[\"complete\"])\n    ents = [f for b in semantic.plan(k, out_dir=out)[\"batches\"] for f in b[\"files\"]]\n    check(\"status: the eligibility rule is the one semantic-plan uses\",\n          len({e[\"rel\"] for e in ents}) == st[\"semantic\"][\"eligible_contents\"])\n    recs = {\"files\": {e[\"key\"]: {\"summary\": f\"read {e['rel']}\", \"nodes\": [{\"label\": f\"Point {e['rel']}\"}],\n                                 \"edges\": []} for e in ents}}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps(recs), encoding=\"utf-8\")\n    semantic.merge(out)\n    st = status(out / \"graph.json\")\n    check(\"status: after reading every document the pass is complete\",\n          st[\"semantic\"][\"missing\"] == 0 and st[\"semantic\"][\"merged\"] == 4)\n\n    code_out = tmp / \"truth_code_out\"\n    res = build(k, out=code_out, quiet=True, code_only=True)\n    st2 = status(code_out / \"graph.json\")\n    rendered = render_status(st2)\n    check(\"status: a --code-only build is 'partial', naming the documents it left out\",\n          st2[\"complete_label\"] == \"partial\" and not st2[\"coverage\"][\"full\"]\n          and any(\"code-only\" in r for r in st2[\"coverage\"][\"restricted_by\"])\n          and \"partial\" in rendered and res[\"files\"] == 1)\n    knowledge.forget()\n\n\ndef _resolution_checks(tmp, check):\n    \"\"\"3.1/3.2: the kind of node decides before 'same file', and methods are reachable as Class.method.\"\"\"\n    import json\n    from . import knowledge, semantic\n    from .build import build\n    from .graph import Graph\n\n    k = tmp / \"resolve\"\n    (k / \"src\").mkdir(parents=True)\n    (k / \"src\" / \"a.py\").write_text(\"class Foo:\\n    def run(self):\\n        return 1\\n\", encoding=\"utf-8\")\n    (k / \"map.md\").write_text(\"# Code map\\n\\n## `src/a.py`\\n\\nThe module.\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    out = Path(build(k, quiet=True)[\"out\"])\n    semantic.plan(k, out_dir=out)\n    rec = {\"files\": {\"map.md\": {\"summary\": \"code map\",\n                               \"nodes\": [{\"label\": \"startup path\", \"type\": \"concept\"}],\n                               \"edges\": [{\"source\": \"startup path\", \"target\": \"src/a.py\", \"relation\": \"documents\"},\n                                         {\"source\": \"startup path\", \"target\": \"src/a.py::Foo.run\",\n                                          \"relation\": \"explains\"},\n                                         {\"source\": \"startup path\", \"target\": \"Foo.run\", \"relation\": \"mentions\"}]}}}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps(rec), encoding=\"utf-8\")\n    semantic.merge(out)\n    build(k, quiet=True)\n    g = Graph.load(out / \"graph.json\")\n    sem = [e for e in g.edges if e.get(\"semantic\")]\n    targets = {e[\"relation\"]: e[\"target\"] for e in sem}\n    check(\"resolution: a path mentioned in a code map links to the file, not to a heading repeating it\",\n          targets.get(\"documents\") == \"file:src/a.py\")\n    check(\"resolution: a method is reachable as path::Class.method and as Class.method\",\n          targets.get(\"explains\") == \"src/a.py::Foo.run\" and targets.get(\"mentions\") == \"src/a.py::Foo.run\")\n    knowledge.forget()\n\n\ndef _upkeep_checks(tmp, check):\n    \"\"\"4.1/4.3/4.4 and group 5: cheap upkeep of a living map.\"\"\"\n    import json\n    from . import knowledge, semantic\n    from .build import build\n\n    k = tmp / \"upkeep\"\n    k.mkdir()\n    body = \"\".join(f\"## Section {i}\\n\\nDecision {i}: approval is required because of rule {i}.\\n\\n\" for i in range(220))\n    (k / \"PROGRESS.md\").write_text(body, encoding=\"utf-8\")\n    (k / \"run.cmd\").write_text(\"@echo off\\r\\ncall :start\\r\\n\", encoding=\"utf-8\")\n    (k / \".gitignore\").write_text(\"secret.log\\n\", encoding=\"utf-8\")\n    (k / \"secret.log\").write_text(\"hidden but wanted\\n\", encoding=\"utf-8\")\n    knowledge.forget()\n    out = Path(build(k, quiet=True)[\"out\"])\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    check(\"detect: .cmd/.bat launchers are code, not documents\",\n          manifest[\"run.cmd\"][\"category\"] == \"code\" and \"secret.log\" not in manifest)\n\n    res = build(k, quiet=True, use_gitignore=False)\n    res2 = build(k, quiet=True)  # plain rebuild: the choice must survive\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    opts = json.loads((out / \"build_options.json\").read_text(encoding=\"utf-8\"))\n    check(\"build: --no-gitignore is remembered like every other option\",\n          \"secret.log\" in manifest and opts[\"use_gitignore\"] is False and res2[\"files\"] == res[\"files\"])\n    build(k, quiet=True, exclude=[\"*.log\"])\n    build(k, quiet=True, exclude_add=[\"run.cmd\"])\n    opts = json.loads((out / \"build_options.json\").read_text(encoding=\"utf-8\"))\n    manifest = json.loads((out / \"manifest.json\").read_text(encoding=\"utf-8\"))\n    check(\"build: --exclude-add adds to the remembered patterns instead of replacing them\",\n          set(opts[\"exclude\"]) == {\"*.log\", \"run.cmd\"} and \"run.cmd\" not in manifest and \"secret.log\" not in manifest)\n    build(k, quiet=True, exclude=[])\n\n    plan1 = semantic.plan(k, out_dir=out, max_part_chars=6000)\n    ents = [f for b in plan1[\"batches\"] for f in b[\"files\"] if f[\"rel\"] == \"PROGRESS.md\"]\n    check(\"semantic: a long document is split into parts\", len(ents) >= 3)\n    recs = {\"files\": {e[\"key\"]: {\"summary\": f\"part {e['part']}\", \"nodes\": [{\"label\": f\"Rule {e['part']}\"}],\n                                 \"edges\": []} for e in ents}}\n    (out / \"semantic\" / \"results\" / \"batch_1.json\").write_text(json.dumps(recs), encoding=\"utf-8\")\n    semantic.merge(out)\n    (k / \"PROGRESS.md\").write_text(body + \"## Section 220\\n\\nDecision 220: a new paragraph.\\n\", encoding=\"utf-8\")\n    build(k, quiet=True)\n    plan2 = semantic.plan(k, out_dir=out, max_part_chars=6000)\n    again = [f for b in plan2[\"batches\"] for f in b[\"files\"] if f[\"rel\"] == \"PROGRESS.md\"]\n    check(\"semantic: appending to a long document re-reads only the changed part (parts cached by their own text)\",\n          len(again) == 1 and len(plan2.get(\"reused_parts\", [])) == len(ents) - 1)\n\n    plan3 = semantic.plan(k, out_dir=out, include_code=True, redo=(\"*\",))\n    rels = {f[\"rel\"] for b in plan3[\"batches\"] for f in b[\"files\"]}\n    check(\"semantic: --include-code plans code files so a causal layer can sit on the code itself\",\n          \"run.cmd\" in rels and plan3[\"include_code\"] is True)\n    plan4 = semantic.plan(k, out_dir=out, redo=(\"PROG*.md\",))\n    check(\"semantic: --redo accepts glob patterns\",\n          any(f[\"rel\"] == \"PROGRESS.md\" for b in plan4[\"batches\"] for f in b[\"files\"]))\n\n    build(k, quiet=True)   # settles the graph produced by the merge above\n    build(k, quiet=True)   # snapshots that settled state once\n    hist = sorted(d.name for d in (out / \"history\").iterdir()) if (out / \"history\").is_dir() else []\n    build(k, quiet=True)\n    build(k, quiet=True)\n    hist2 = sorted(d.name for d in (out / \"history\").iterdir())\n    check(\"history: no snapshot is written when the graph did not change\", hist2 == hist and len(hist) > 0)\n    (k / \"new.md\").write_text(\"# New\\n\\nAnother decision.\\n\", encoding=\"utf-8\")\n    build(k, quiet=True, history_keep=1)\n    opts = json.loads((out / \"build_options.json\").read_text(encoding=\"utf-8\"))\n    hist3 = sorted(d.name for d in (out / \"history\").iterdir())\n    check(\"history: --history-keep is remembered and applied\", opts[\"history_keep\"] == 1 and len(hist3) == 1)\n    knowledge.forget()\n\n\ndef _fmp4_roundtrip(tmp):\n    \"\"\"Build two synthetic fragmented MP4s (as DASH video/audio), merge them, and verify every sample's bytes.\"\"\"\n    import struct\n    from . import mp4defrag as m\n\n    def box(t, p):\n        return struct.pack(\">I4s\", 8 + len(p), t) + p\n\n    def full(t, p, v=0, f=0):\n        return box(t, struct.pack(\">I\", (v << 24) | f) + p)\n\n    def fmp4(handler, payloads):\n        stbl = box(b\"stbl\", full(b\"stsd\", struct.pack(\">I\", 0)) + full(b\"stts\", b\"\\0\" * 4) + full(b\"stsc\", b\"\\0\" * 4)\n                   + full(b\"stsz\", b\"\\0\" * 8) + full(b\"stco\", b\"\\0\" * 4))\n        trak = box(b\"trak\", full(b\"tkhd\", b\"\\0\" * 8 + struct.pack(\">I\", 1) + b\"\\0\" * 64)\n                   + box(b\"mdia\", full(b\"mdhd\", b\"\\0\" * 8 + struct.pack(\">II\", 1000, 0) + b\"\\0\" * 4)\n                         + full(b\"hdlr\", b\"\\0\" * 4 + handler + b\"\\0\" * 13) + box(b\"minf\", stbl)))\n        moov = box(b\"moov\", full(b\"mvhd\", b\"\\0\" * 8 + struct.pack(\">II\", 1000, 0) + b\"\\0\" * 76 + struct.pack(\">I\", 2))\n                   + box(b\"mvex\", full(b\"trex\", struct.pack(\">IIIII\", 1, 1, 40, 0, 0))) + trak)\n        out = box(b\"ftyp\", b\"iso6\\0\\0\\0\\0iso6\") + moov\n        for group in payloads:\n            trun = full(b\"trun\", struct.pack(\">Ii\", len(group), 0)\n                        + b\"\".join(struct.pack(\">I\", len(g)) for g in group), f=0x201)\n            traf = box(b\"traf\", full(b\"tfhd\", struct.pack(\">I\", 1), f=0x20000) + full(b\"tfdt\", struct.pack(\">I\", 0)) + trun)\n            moof = bytearray(box(b\"moof\", box(b\"mfhd\", b\"\\0\" * 8) + traf))\n            struct.pack_into(\">i\", moof, moof.find(b\"trun\") + 12, len(moof) + 8)   # data starts after mdat header\n            out += bytes(moof) + box(b\"mdat\", b\"\".join(group))\n        return out\n\n    try:\n        v = [[b\"V0\" * 50, b\"V1\" * 30], [b\"V2\" * 70]]\n        a = [[b\"A0\" * 10, b\"A1\" * 12, b\"A2\" * 9]]\n        (tmp / \"v.mp4\").write_bytes(fmp4(b\"vide\", v))\n        (tmp / \"a.m4a\").write_bytes(fmp4(b\"soun\", a))\n        if not (m.is_fragmented(tmp / \"v.mp4\") and m.is_fragmented(tmp / \"a.m4a\")):\n            return False\n        info = m.defragment([tmp / \"v.mp4\", tmp / \"a.m4a\"], tmp / \"merged.mp4\")\n        data = (tmp / \"merged.mp4\").read_bytes()\n        if m.is_fragmented(tmp / \"merged.mp4\") or info[\"tracks\"] != [\"vide\", \"soun\"]:\n            return False\n        moov = next(b for b in m._boxes(data) if b[0] == b\"moov\")\n        got = []\n        for trak in m._children(data, moov, b\"trak\"):\n            stbl = m._child(data, m._child(data, m._child(data, trak, b\"mdia\"), b\"minf\"), b\"stbl\")\n            sizes_p = m._body(data, m._child(data, stbl, b\"stsz\"))\n            sizes = struct.unpack(f\">{struct.unpack('>I', sizes_p[8:12])[0]}I\", sizes_p[12:])\n            co = m._body(data, m._child(data, stbl, b\"co64\"))\n            offs = struct.unpack(f\">{struct.unpack('>I', co[4:8])[0]}Q\", co[8:])\n            stsc = m._body(data, m._child(data, stbl, b\"stsc\"))\n            runs = [struct.unpack(\">III\", stsc[8 + 12 * i:20 + 12 * i]) for i in range(struct.unpack(\">I\", stsc[4:8])[0])]\n            per_chunk = []\n            for ci in range(len(offs)):\n                per_chunk.append([r[1] for r in runs if r[0] <= ci + 1][-1])\n            k = 0\n            for off, count in zip(offs, per_chunk):\n                for _ in range(count):\n                    got.append(data[off:off + sizes[k]])\n                    off += sizes[k]\n                    k += 1\n        return got == [s for g in v for s in g] + [s for g in a for s in g]\n    except Exception:\n        return False\n\n\nif __name__ == \"__main__\":\n    sys.exit(run())\n");
